targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	api.state.formFieldAndValues["token_format"] = "opaque";
	api.state.formFieldAndValues["sub_claim"] = "user_name";
	return {
		route: "inbound-integrations",
		fields: {
            timestamp: Date.now()
        },
		params: null,
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null
	};
})

